def admit_roster_panel_source(source,main_source,reused_sources,transport_source,movement_source,entry_registry_source):
    """Complete original source and inverse admission, not a runtime gate."""
    tree=ast.parse(source)
    if ast.dump(tree,include_attributes=False)!=EXPECTED_MODULE_AST:
        raise ValueError('complete admitted roster continuation module differs')
    values={node.targets[0].id:ast.literal_eval(node.value) for node in tree.body
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name)
        and node.targets[0].id in ('MAIN_ENTRIES','CALL_COUNTS','EXPECTED_MAIN_SOURCE','EXPECTED_REUSED_SOURCE')}
    if set(reused_sources)!=set(values['EXPECTED_REUSED_SOURCE']):raise ValueError('all exact roster dependency sources required')
    for path,names in values['EXPECTED_REUSED_SOURCE'].items():
        nodes={node.name:node for node in ast.parse(reused_sources[path]).body if isinstance(node,ast.FunctionDef)}
        for name,text in names.items():
            if name not in nodes or ast.dump(nodes[name],include_attributes=False)!=ast.dump(ast.parse(text).body[0],include_attributes=False):
                raise ValueError('complete mature roster dependency differs: '+name)
    registry={node.targets[0].id:ast.literal_eval(node.value) for node in ast.parse(entry_registry_source).body
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name)
        and node.targets[0].id in ('EXPECTED_MODULE_ASTS','EXPECTED_DEPENDENCY_ASTS')}
    transport='tools/high_level_movement_v2/business_scene_transport.py'
    movement='tools/high_level_main_flows/business_movement_support.py'
    if ast.dump(ast.parse(transport_source),include_attributes=False)!=registry['EXPECTED_MODULE_ASTS'][transport]:
        raise ValueError('existing exact transport module registration differs')
    path=next(node for node in ast.parse(movement_source).body if isinstance(node,ast.FunctionDef) and node.name=='build_path_fields')
    if ast.dump(path,include_attributes=False)!=registry['EXPECTED_DEPENDENCY_ASTS'][movement]['build_path_fields']:
        raise ValueError('existing exact path algorithm registration differs')
    definitions=[node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name=='_roster_main_tree']
    if len(definitions)!=1:raise ValueError('complete roster source inverse utility required')
    namespace=dict(ast=ast,copy=copy,_dump=lambda node:ast.dump(node,include_attributes=False),**values)
    exec(compile(ast.Module(body=definitions,type_ignores=[]),'<roster source inverse>','exec'),namespace)
    compile(namespace['_roster_main_tree'](ast.parse(main_source)),'<complete roster main>','exec',dont_inherit=True)
    return dict(confidence='confirmed_source_only',complete_FN_and_module_inverses=True,
        new_algorithm_bodies=0,formal_credit=0,strict_pending_unchanged=46004,
        game=False,fixture=False,normal_API=False,native=False,hash=False)
